insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('d690e584-6831-4f20-9667-9d03af036f66', '664ee2dd-cff4-4b4f-882d-08fd0a2b716d', $$inleiding: de Snellenkaart$$,
   $$wiskunde-a-havo-2021-i-visus-context1.png$$,
   $$Om te bepalen hoe goed iemands ogen functioneren, wordt vaak gebruikgemaakt van de Snellenkaart. De letters op deze kaart moeten vanaf een afstand van 20 feet (ongeveer 6 meter) worden gelezen. Zie de figuur.$$, 'inline'),
  ('0e88db67-4c83-4786-b4ff-f67fe0081362', '664ee2dd-cff4-4b4f-882d-08fd0a2b716d', $$figuur: Snellenkaart met regels 1 t/m 11$$,
   $$wiskunde-a-havo-2021-i-visus-context2.png$$,
   $$figuur
Snellenkaart met regels 1 t/m 11: regel 1 20/200, regel 2 20/100, regel 3 20/70, regel 4 20/50, regel 5 20/40, regel 6 20/30, regel 7 20/25, regel 8 20/20, regel 9 20/15, regel 10 20/13, regel 11 20/10$$, 'inline'),
  ('00104ef2-6b33-47f8-9b8a-9994b1691d58', '664ee2dd-cff4-4b4f-882d-08fd0a2b716d', $$visus-score S, formule 1 en formule 2, betekenis van S$$,
   $$wiskunde-a-havo-2021-i-visus-context3.png$$,
   $$De visus is een maat voor de gezichtsscherpte. Deze maat kan met behulp van de Snellenkaart worden uitgedrukt in een score S. Iemand met normaal functionerende ogen kan de letters op regel 8 nog wel lezen, maar de letters op regel 9 niet meer. Bij normaal functionerende ogen hoort een score S = 20/20 = 1. Als een persoon nog kleinere letters kan lezen, dan is de score S groter dan 1. Bij de onderste regel 11 hoort bijvoorbeeld de score S = 20/10 = 2.
S = 10⁻ᴹ (formule 1)
S = 10⁽ᴱ⁻⁸⁵⁾ᐟ⁵⁰ (formule 2
Iemand met S = 0,5 moet alles van tweemaal zo dichtbij bekijken om hetzelfde op de Snellenkaart te kunnen zien als iemand met S = 1. Iemand met S = 0,1 moet tienmaal zo dichtbij staan, enzovoort.$$, 'inline'),
  ('2c455dd2-79b8-44b3-b24b-cf1087fc5aaf', '664ee2dd-cff4-4b4f-882d-08fd0a2b716d', $$Klaas en Lidy laten hun visus meten$$,
   $$wiskunde-a-havo-2021-i-visus-context4.png$$,
   $$Klaas en Lidy laten hun visus meten. Klaas kan regel 2 nog wel lezen, maar regel 3 niet meer. Lidy kan regel 7 nog wel lezen, maar regel 8 niet meer.$$, 'inline'),
  ('fcffc4d9-8254-4ee5-94d5-7849bcec3531', '664ee2dd-cff4-4b4f-882d-08fd0a2b716d', $$logMAR-schaal (M) en ETDRS-letterscore (E)$$,
   $$wiskunde-a-havo-2021-i-visus-context5.png$$,
   $$Er zijn meerdere maten voor de gezichtsscherpte. Voorbeelden hiervan zijn de logMAR-schaal1) en de ETDRS-letterscore2).
Het verband tussen de score S volgens de Snellenkaart en de score M op de logMAR-schaal wordt gegeven door formule 1. Voor het verband tussen de score S en de ETDRS-letterscore E geldt formule 2:$$, 'inline'),
  ('17efb6ba-9964-4662-a54f-569786e8f9b2', '664ee2dd-cff4-4b4f-882d-08fd0a2b716d', $$slechtziend: S tussen 0,05 en 0,3$$,
   $$wiskunde-a-havo-2021-i-visus-context6.png$$,
   $$De Wereldgezondheidsorganisatie noemt mensen met een score S tussen 0,05 en 0,3 slechtziend.$$, 'inline'),
  ('381a4f3d-fc75-4abe-9f1e-02fb2c8d02b2', '664ee2dd-cff4-4b4f-882d-08fd0a2b716d', $$CBR-keuringseis S minimaal 0,5; Janne E = 75$$,
   $$wiskunde-a-havo-2021-i-visus-context7.png$$,
   $$Het Centraal Bureau Rijvaardigheidsbewijzen (CBR) stelt als keuringseis dat S minimaal 0,5 moet zijn. Janne heeft een ETDRS-letterscore van 75.$$, 'inline'),
  ('22386b60-5b51-4991-ae9b-2a69bec58cd5', '664ee2dd-cff4-4b4f-882d-08fd0a2b716d', $$als M groter wordt, wordt E kleiner$$,
   $$wiskunde-a-havo-2021-i-visus-context8.png$$,
   $$Aan de hand van formule 1 en formule 2 kan beredeneerd worden dat als M groter wordt, E kleiner zal worden.$$, 'inline'),
  ('1f16a9cd-5a66-4f9f-a80b-2c1d912d3cf4', '664ee2dd-cff4-4b4f-882d-08fd0a2b716d', $$gecombineerd verband tussen M en E$$,
   $$wiskunde-a-havo-2021-i-visus-context9.png$$,
   $$Door de twee formules te combineren, kan het volgende verband tussen M en E worden afgeleid:
−M = (E − 85)/50$$, 'inline'),
  ('d280b1c5-3286-498f-b5f1-1fc857f3dcf3', '664ee2dd-cff4-4b4f-882d-08fd0a2b716d', $$noten: logMAR en ETDRS$$,
   $$wiskunde-a-havo-2021-i-visus-context10.png$$,
   $$noot 1 logMAR = Logarithm of the Minimum Angle of Resolution noot 2 ETDRS = Early Treatment Diabetic Retinopathy Study$$, 'inline'),
  ('c89cffa8-6f82-495a-b26d-a7068926c8fe', 'a22de7dd-daaa-4793-8555-88574d6fc9d3', $$inleiding: klarinet, bereik en octaaf (met foto)$$,
   $$wiskunde-a-havo-2021-i-klarinet-context1.png$$,
   $$Een klarinet is een houten blaasinstrument. Alle mogelijke tonen die op het instrument kunnen worden gespeeld, worden samen het bereik genoemd. Het bereik van een klarinet is bijna vier octaven. Een octaaf bestaat uit 12 opeenvolgende toonafstanden. Zie de tabel. Elke voorafgaande of opeenvolgende octaaf heeft dezelfde namen voor de tonen in dat octaaf.$$, 'inline'),
  ('76196df7-5846-41fd-859e-a2fe698a289e', 'a22de7dd-daaa-4793-8555-88574d6fc9d3', $$frequentie in Hz, octaaf hoger = twee keer zo groot, exponentieel verband$$,
   $$wiskunde-a-havo-2021-i-klarinet-context2.png$$,
   $$De frequentie van een toon wordt gegeven in hertz (Hz), dit is het aantal trillingen per seconde. Bij een hogere toon hoort een hogere frequentie. Als je eenzelfde toon één octaaf hoger speelt, wordt de frequentie twee keer zo groot. Er bestaat een exponentieel verband tussen de frequenties en de tonen in de tabel: van elke volgende toon neemt de frequentie met een vast percentage toe. In de tabel zie je van enkele tonen de frequenties.$$, 'inline'),
  ('996767c2-4d38-47fa-a7d6-106e36900a68', 'a22de7dd-daaa-4793-8555-88574d6fc9d3', $$tabel: voorbeeld van een octaaf met frequenties$$,
   $$wiskunde-a-havo-2021-i-klarinet-context3.png$$,
   $$tabel Voorbeeld van een octaaf
toon: A, Bes, B, C, Des, D, Es, E, F, Ges, G, As, A
frequentie (Hz): A 440; D 587; A 880 (overige vakjes leeg)$$, 'inline'),
  ('df7438d8-6bc8-4ee6-81e5-4b1ab9e6b0ec', 'a22de7dd-daaa-4793-8555-88574d6fc9d3', $$frequentie van de D-toon afgerond op hele Hz$$,
   $$wiskunde-a-havo-2021-i-klarinet-context4.png$$,
   $$In de tabel is de frequentie van de D-toon afgerond op hele Hz.$$, 'inline'),
  ('b3f17216-3ffa-48ee-ac17-bbd8060ff3a9', 'a22de7dd-daaa-4793-8555-88574d6fc9d3', $$figuur: bereik van instrumenten op logaritmische schaal$$,
   $$wiskunde-a-havo-2021-i-klarinet-context5.png$$,
   $$In de figuur wordt op een logaritmische schaalverdeling het bereik van verschillende instrumenten aangegeven.
figuur
liggende balken voor triangel, piano, piccolo, fluit, klarinet, contrafagot, hoorn en trompet; horizontale as: frequentie (Hz), logaritmische schaal met 10, 100, 1000, 10000$$, 'inline'),
  ('61b321ea-3f72-4cbd-84d2-b4eca9952297', 'a22de7dd-daaa-4793-8555-88574d6fc9d3', $$laagste toon klarinet is een D, hoogste een A$$,
   $$wiskunde-a-havo-2021-i-klarinet-context6.png$$,
   $$De laagste toon die een klarinet kan laten horen is een D. De hoogste toon is een A.$$, 'inline'),
  ('adcc2234-27d2-49d2-99b1-8ea4fc970e9d', 'a22de7dd-daaa-4793-8555-88574d6fc9d3', $$formule snelheid van het geluid v = 20√(273 + T)$$,
   $$wiskunde-a-havo-2021-i-klarinet-context7.png$$,
   $$Een klarinettist moet altijd eerst een korte tijd inspelen om de klarinet op een vaste temperatuur van 31 °C te brengen. Als de klarinet koud is, klinken de tonen namelijk lager dan als de klarinet warm is. Dit komt omdat de snelheid van het geluid afhankelijk is van de temperatuur. Dit verband wordt gegeven door de formule:
v = 20√(273 + T)
Hierin is v de snelheid van het geluid (in m/s) en T de temperatuur (in °C).$$, 'inline'),
  ('47c9afab-131f-46a0-9a7b-c0fafcb5705a', 'a22de7dd-daaa-4793-8555-88574d6fc9d3', $$voorbeelden: 342 m/s bij 20 °C, 349 m/s bij 31 °C$$,
   $$wiskunde-a-havo-2021-i-klarinet-context8.png$$,
   $$Met de formule kun je bijvoorbeeld berekenen dat bij een temperatuur van
20 °C de snelheid van het geluid ongeveer 342 m/s is. Bij een temperatuur van 31 °C is deze snelheid ongeveer 349 m/s.$$, 'inline'),
  ('945ad2d3-7bea-46ee-aef9-c16d3076201c', 'a22de7dd-daaa-4793-8555-88574d6fc9d3', $$formule frequentie f = v/(4L)$$,
   $$wiskunde-a-havo-2021-i-klarinet-context9.png$$,
   $$Een toon van de klarinet is te horen als er lucht in de klarinetbuis in trilling gebracht wordt. Door tijdens het spelen gaatjes in de klarinetbuis open of dicht te doen, verandert de lengte L van het gedeelte van de klarinetbuis waarin de lucht trilt. De frequentie van een toon die op een klarinet gespeeld wordt, kun je berekenen met de formule:
f = v/(4L)
Hierin is f de frequentie van de toon (in Hz), v de snelheid van het geluid in de klarinet (in m/s) en L de lengte van het gedeelte van de klarinetbuis waarin de lucht trilt (in m).$$, 'inline'),
  ('5b75127b-bbc9-4070-9cc9-6fd341239b87', 'a22de7dd-daaa-4793-8555-88574d6fc9d3', $$Els speelt 440 Hz bij 31 °C$$,
   $$wiskunde-a-havo-2021-i-klarinet-context10.png$$,
   $$Els speelt op haar klarinet met de eerder genoemde temperatuur van
31 °C een toon die klinkt met een frequentie van precies 440 Hz. Deze toon had bij het begin van het inspelen op de klarinet met een temperatuur van 20 °C een andere frequentie dan nu de klarinet een temperatuur van 31 °C heeft.$$, 'inline'),
  ('5eca892f-5203-49dd-a2b5-a3440fd8f1e9', '39a96e5c-56d6-415e-955a-dbb1c883725a', $$inleiding: wachttijdformule W = r·S / (2(1 − r)) (met foto)$$,
   $$wiskunde-a-havo-2021-i-de-voorsteekpas-context1.png$$,
   $$In de zomermaanden worden pretparken druk bezocht. De wachttijden voor de attracties kunnen dan sterk oplopen. De wachttijd voor een attractie kan berekend worden met de formule:
W = r·S / (2(1 − r))
Hierin is W de gemiddelde wachttijd van een willekeurige bezoeker in minuten en r de bezettingsgraad van de attractie (0 < r < 1). Als voor de bezettingsgraad bijvoorbeeld geldt dat r = 0,85, betekent dit dat gemiddeld 85% van de plaatsen in de attractie bezet is. S is de bedieningstijd per bezoeker in seconden. Als bijvoorbeeld een attractie elke 10 minuten 100 bezoekers kan bedienen, geldt:
S = 6 ( = 600 seconden / 100 bezoekers).$$, 'inline'),
  ('a0a22701-9e45-4855-88ae-957eadcbd01e', '39a96e5c-56d6-415e-955a-dbb1c883725a', $$Vampire: bezettingsgraad 98%, 80 bezoekers per vier minuten$$,
   $$wiskunde-a-havo-2021-i-de-voorsteekpas-context2.png$$,
   $$In Walibi Belgium is de achtbaan Vampire een populaire attractie, die in de zomermaanden een bezettingsgraad van 98% heeft. De Vampire kan iedere vier minuten 80 bezoekers bedienen.$$, 'inline'),
  ('04135f9a-69cb-49b1-b9d4-a2a6c1392c37', '39a96e5c-56d6-415e-955a-dbb1c883725a', $$introductie voorsteekpas in 2013$$,
   $$wiskunde-a-havo-2021-i-de-voorsteekpas-context3.png$$,
   $$In de zomer van 2013 introduceerde Walibi Belgium een zogenoemde voorsteekpas. Met deze pas kan een bezoeker voorrang krijgen bij de attracties. Daardoor zal de wachttijd voor een bezoeker zonder deze pas langer worden.$$, 'inline'),
  ('2a2dd9bc-9f27-4c75-9e4f-8d323fdf5861', '39a96e5c-56d6-415e-955a-dbb1c883725a', $$formules voor Wp en Wz met aandeel a$$,
   $$wiskunde-a-havo-2021-i-de-voorsteekpas-context4.png$$,
   $$Er zijn nu twee formules voor de wachttijd voor een attractie, namelijk een formule voor de gemiddelde wachttijd Wp in minuten van een bezoeker met de voorsteekpas en een formule voor de gemiddelde wachttijd Wz in minuten van een bezoeker zonder voorsteekpas:
Wp = r·S / (2(1 − a·r)) en Wz = r·S / (2(1 − r)(1 − a·r))
Hierin is a het gedeelte van de bezoekers met een voorsteekpas (0 < a < 1).$$, 'inline'),
  ('c858e525-7c1f-4705-9cdc-e23b84a62a2d', '39a96e5c-56d6-415e-955a-dbb1c883725a', $$Cobra: r = 0,95 en S = 6$$,
   $$wiskunde-a-havo-2021-i-de-voorsteekpas-context5.png$$,
   $$Een andere bekende attractie van Walibi Belgium is de Cobra. Deze attractie heeft een bezettingsgraad van 95% (dus r = 0,95) en een bedieningstijd van 6 seconden per bezoeker (dus S = 6).$$, 'inline'),
  ('87614909-4257-4513-a020-1c97b90d08c1', '39a96e5c-56d6-415e-955a-dbb1c883725a', $$6 juli 2013: a = 0,10$$,
   $$wiskunde-a-havo-2021-i-de-voorsteekpas-context6.png$$,
   $$Op 6 juli 2013 kocht 10% van de bezoekers een voorsteekpas, dus a = 0,10.$$, 'inline'),
  ('e3dd9083-0193-47e2-97fd-4d775a5f1d7d', '39a96e5c-56d6-415e-955a-dbb1c883725a', $$wachttijd zonder voorsteekpas bij de Cobra maximaal 80 minuten$$,
   $$wiskunde-a-havo-2021-i-de-voorsteekpas-context7.png$$,
   $$De wachttijd van de bezoekers zonder voorsteekpas wordt groter als meer bezoekers een voorsteekpas kopen. De directie van Walibi Belgium wil dat de wachttijd van bezoekers zonder voorsteekpas bij de Cobra maximaal 80 minuten is.$$, 'inline'),
  ('c1c96dfb-c749-4f62-add0-7e67f4fe1384', '39a96e5c-56d6-415e-955a-dbb1c883725a', $$herleide formule Wz voor de Cobra$$,
   $$wiskunde-a-havo-2021-i-de-voorsteekpas-context8.png$$,
   $$Voor de Cobra kan de formule van de wachttijd voor bezoekers zonder voorsteekpas worden herleid tot:
Wz = 5,7 / (0,10 − ...·a)$$, 'inline'),
  ('18470106-f8d7-470b-88a2-eed3b6c2c6fb', '43cbfc52-fd5d-406d-9110-454373ef34cc', $$inleiding: populatie en aselecte steekproef van 3260 scholieren$$,
   $$wiskunde-a-havo-2021-i-nibud-scholierenonderzoek-context1.png$$,
   $$Het Nibud Scholierenonderzoek brengt het financiële gedrag van scholieren in het voortgezet onderwijs in kaart. De populatie van dit onderzoek bestaat uit alle vmbo-, havo- en vwo- scholieren in de leeftijd van 12 tot en met 18 jaar. Van een aselecte steekproef van 3260 scholieren uit de populatie zijn gegevens beschikbaar gekomen via online vragenlijsten. We gaan ervan uit dat deze steekproef representatief is.$$, 'inline'),
  ('84f2d651-b545-418d-b97a-eae28712b857', '43cbfc52-fd5d-406d-9110-454373ef34cc', $$1530 scholieren hebben een bijbaantje$$,
   $$wiskunde-a-havo-2021-i-nibud-scholierenonderzoek-context2.png$$,
   $$1530 scholieren in de steekproef hebben een bijbaantje.$$, 'inline'),
  ('242c9a6f-2995-493b-8c70-4eea0d6bb40c', '43cbfc52-fd5d-406d-9110-454373ef34cc', $$tabel 1: gemiddeld aantal uren per week bijbaan$$,
   $$wiskunde-a-havo-2021-i-nibud-scholierenonderzoek-context3.png$$,
   $$In het rapport staat een tabel met informatie over het gemiddeld aantal uren per week dat een scholier met een bijbaantje werkt (zie tabel 1).
tabel 1 Bijbaan: gemiddeld aantal uren per week
onderwijsniveau en klas | bijbaan (uren per week)
vmbo bovenbouw (klas 3 en 4) | 9
havo / vwo (klas 3) | 6
havo bovenbouw (klas 4 en 5) | 8
vwo bovenbouw (klas 4, 5 en 6) | 6$$, 'inline'),
  ('4f51bb00-0007-4f11-b1e2-0b18e044a0a6', '43cbfc52-fd5d-406d-9110-454373ef34cc', $$verschil havo- en vwo-bovenbouw in aantal werkuren$$,
   $$wiskunde-a-havo-2021-i-nibud-scholierenonderzoek-context4.png$$,
   $$Als je met behulp van het formuleblad een uitspraak wilt doen over het verschil tussen havo bovenbouwscholieren met een bijbaantje en vwo bovenbouwscholieren met een bijbaantje in het aantal uren dat zij werken, dan heb je meer informatie of misschien wel heel andere informatie nodig dan die in tabel 1 staat.$$, 'inline'),
  ('d06f5659-dc1e-4dc7-89f2-e06d42e8b0ef', '43cbfc52-fd5d-406d-9110-454373ef34cc', $$gemiddelde 112 en mediaan 65 euro; figuur: drie frequentieverdelingen A, B en C$$,
   $$wiskunde-a-havo-2021-i-nibud-scholierenonderzoek-context5.png$$,
   $$In de steekproef bedroeg het gemiddelde inkomen van een scholier met een bijbaantje 112 euro per maand. De mediaan was 65 euro. In de figuur zie je drie frequentieverdelingen afgebeeld waarvan er één de frequentieverdeling van het inkomen per maand van een scholier met een bijbaantje in de steekproef weergeeft.
figuur
drie frequentieverdelingen, aangeduid met A, B en C$$, 'inline'),
  ('cddd3d8c-56f3-4df5-9284-ab83d92dbfeb', '43cbfc52-fd5d-406d-9110-454373ef34cc', $$tabel 2: inkomen per maand van 15- en 16-jarigen$$,
   $$wiskunde-a-havo-2021-i-nibud-scholierenonderzoek-context6.png$$,
   $$Het Nibud wil het inkomen van scholieren met een bijbaantje ook per onderwijsniveau in kaart brengen. Dat hebben ze gedaan door tabel 2 in hun onderzoeksrapport te zetten.
tabel 2 Bijbaan: inkomen (in euro) per maand van 15- en 16-jarigen
onderwijsniveau en klas | gemiddelde | mediaan
vmbo bovenbouw (klas 3 en 4) | 149 | 107
havo / vwo (klas 3) | 93 | 65
havo bovenbouw (klas 4 en 5) | 181 | 142
vwo bovenbouw (klas 4, 5 en 6) | 130 | 101$$, 'inline'),
  ('7a1b0f7c-1541-4d5d-81c3-64aad72a259c', '43cbfc52-fd5d-406d-9110-454373ef34cc', $$tabel 2 gebaseerd op 15- en 16-jarigen$$,
   $$wiskunde-a-havo-2021-i-nibud-scholierenonderzoek-context7.png$$,
   $$Deze tabel is gebaseerd op scholieren in de steekproef die 15 of 16 jaar zijn.$$, 'inline'),
  ('2f7b026f-f6cb-4c7b-9433-95ba5769fb6b', '43cbfc52-fd5d-406d-9110-454373ef34cc', $$spijt na aankoop: 600 jongens en 600 meisjes; tabel 3$$,
   $$wiskunde-a-havo-2021-i-nibud-scholierenonderzoek-context8.png$$,
   $$Voor het laatste onderdeel van deze opgave kijken we niet naar het inkomen van scholieren, maar naar een aspect van de uitgaven van scholieren. Dit aspect betreft de vraag hoe vaak scholieren spijt hebben na het doen van een aankoop. Van 1200 aselect gekozen respondenten (600 jongens en 600 meisjes) is bekend hoe vaak zij spijt hebben na het doen van een aankoop. De resultaten zijn weergegeven in een relatieve frequentietabel, zie tabel 3.
tabel 3 Spijt na het doen van een aankoop
| jongens | meisjes | totaal
nooit / zelden | 16% | 8% | 12%
meestal niet | 65% | 61% | 63%
meestal wel | 19% | 29% | 24%
vaak / altijd | 0% | 2% | 1%$$, 'inline'),
  ('05bd159d-4abe-4ad9-9ffe-8fb65fbc72bd', '2ef969f9-2fc9-42d5-bb44-fa70ae1b413f', $$inleiding en figuur: postzegelprijs en aantal brieven/kaarten 2005-2016$$,
   $$wiskunde-a-havo-2021-i-postzegels-context1.png$$,
   $$Mensen sturen steeds minder brieven en kaarten. Postzegels zijn in Nederland de afgelopen jaren flink duurder geworden. Elk jaar op 1 januari wordt de prijs zo nodig aangepast.
In de figuur zie je de postzegelprijs (in centen) en het aantal brieven/kaarten (in miljarden) dat bezorgd werd in de jaren 2005-2016.
figuur
staafdiagram brieven/kaarten (miljard) per jaar 2005-2016 (verticale as van 2 tot 8) met lijn van de postzegelprijs, met de labels 39 ct, 44 ct, 44 ct, 46 ct, 50 ct, 54 ct, 64 ct, 69 ct, 73 ct$$, 'inline'),
  ('bb867de3-1fa0-4433-994d-4407e6e9b970', '2ef969f9-2fc9-42d5-bb44-fa70ae1b413f', $$voorbeeld aflezen figuur: 2007$$,
   $$wiskunde-a-havo-2021-i-postzegels-context2.png$$,
   $$Je kunt in de figuur bijvoorbeeld aflezen dat op 1 januari 2007 de postzegelprijs 44 cent was en dat er in het jaar 2007 4,8 miljard brieven/kaarten werden bezorgd.$$, 'inline'),
  ('2f56c86f-6e77-40c2-b039-dba626d6c76c', '2ef969f9-2fc9-42d5-bb44-fa70ae1b413f', $$postzegelprijs 44 cent in 2010 en 64 cent in 2014, exponentiële groei$$,
   $$wiskunde-a-havo-2021-i-postzegels-context3.png$$,
   $$Op 1 januari 2010 kostte een postzegel 44 cent. Op 1 januari 2014 was de prijs gestegen tot 64 cent. Veronderstel dat in de periode 2010-2014 de postzegelprijs exponentieel groeide.$$, 'inline'),
  ('d9cc4867-a659-4de7-94e8-7d3b433d30f9', '2ef969f9-2fc9-42d5-bb44-fa70ae1b413f', $$aantal brieven/kaarten 2010-2016 lineaire afname$$,
   $$wiskunde-a-havo-2021-i-postzegels-context4.png$$,
   $$In de periode 2010-2016 nam het aantal brieven/kaarten dat jaarlijks werd bezorgd bij benadering lineair af. Er werd in 2016 voorspeld dat deze afname zich nog een aantal jaren op deze manier zou voortzetten.$$, 'inline'),
  ('156d3605-adc5-4b76-926a-e2a287d6ab22', '2ef969f9-2fc9-42d5-bb44-fa70ae1b413f', $$tabel: aantal, opbrengst en postzegelprijs 2015 en 2016$$,
   $$wiskunde-a-havo-2021-i-postzegels-context5.png$$,
   $$In de tabel zie je voor 2015 en 2016 onder andere het aantal bezorgde brieven/kaarten en de bijbehorende opbrengst. Dit is het totale bedrag dat aan postzegels is verkocht dat op al die brieven/kaarten is geplakt. De opbrengst in 2016 was lager dan die in 2015, ondanks de verhoging van de postzegelprijs van € 0,69 naar € 0,73.
tabel brieven/kaarten
jaar | aantal stuks (in miljoenen) | opbrengst (in miljoenen euro’s) | postzegelprijs (cent)
2015 | 2401 | 1961 | 69
2016 | 2213 | 1877 | 73$$, 'inline'),
  ('82afd0f8-bd6e-4d5d-9f8b-cdbf559871e1', '2ef969f9-2fc9-42d5-bb44-fa70ae1b413f', $$aantal postzegels per gewichtsklasse$$,
   $$wiskunde-a-havo-2021-i-postzegels-context6.png$$,
   $$Voor het versturen van brieven/kaarten tot 20 gram heb je 1 postzegel nodig. Voor het versturen van brieven/kaarten vanaf 20 gram tot 50 gram moet je 2 postzegels plakken, en vanaf 50 tot 100 gram 3 postzegels. Neem aan dat op alle brieven/kaarten maximaal 3 postzegels zijn geplakt.$$, 'inline'),
  ('61d008ac-63a3-444f-8abf-1ad13a737ff0', '2ef969f9-2fc9-42d5-bb44-fa70ae1b413f', $$2016: 88% met 1 postzegel; vergelijking voor x$$,
   $$wiskunde-a-havo-2021-i-postzegels-context7.png$$,
   $$Neem aan dat in 2016 op 88% van de brieven/kaarten 1 postzegel werd geplakt en op de overige brieven/kaarten 2 of 3 postzegels. Je kunt dan met behulp van de tabel de volgende vergelijking opstellen om het aantal brieven/kaarten met 2 postzegels te berekenen:
0,73·1947,44 + 1,46·x + 2,19·(265,56 − x) = 1877
Hierin is x het aantal brieven/kaarten met 2 postzegels in miljoenen.$$, 'inline'),
  ('cf4d4ce8-ca09-4b12-be68-da9a8d64e929', '92a2ca27-f059-466a-89c7-95a3c20a6f53', $$inleiding: fijnstofemissie door wegvervoer (met foto)$$,
   $$wiskunde-a-havo-2021-i-fijnstofemissie-context1.png$$,
   $$In het rapport Transport en Mobiliteit 2016 van het Centraal Bureau voor de Statistiek staat informatie over de fijnstofemissie (dit is de hoeveelheid fijnstof die vrijkomt) door het vervoer over de weg, uitgesplitst naar personenvervoer en goederenvervoer. Deze hoeveelheid wordt bepaald door het aantal gereden kilometers te vermenigvuldigen met de fijnstofemissie per gereden kilometer.$$, 'inline'),
  ('278f85d2-efa5-4089-ac10-0708dc5dc862', '92a2ca27-f059-466a-89c7-95a3c20a6f53', $$gereden kilometers personen- en goederenvervoer in 1990 en 2014$$,
   $$wiskunde-a-havo-2021-i-fijnstofemissie-context2.png$$,
   $$In 1990 was het aantal gereden kilometers door het personenvervoer 103 200 miljoen en door het goederenvervoer 16 800 miljoen. In 2014 is het aantal gereden kilometers voor het personenvervoer twee keer zo groot geworden als in 1990 en het aantal gereden kilometers voor het goederenvervoer drie keer zo groot. Ondanks de toename van het aantal gereden kilometers is de totale fijnstofemissie door het wegvervoer in 2014 aanzienlijk minder dan in 1990. Dit komt vooral door het gebruik van betere motoren.$$, 'inline'),
  ('31024301-1a1c-4799-90eb-64b3bcb77ba5', '92a2ca27-f059-466a-89c7-95a3c20a6f53', $$onderzoeksvraag: procentuele daling totale emissie 1990-2014$$,
   $$wiskunde-a-havo-2021-i-fijnstofemissie-context3.png$$,
   $$Er moet worden onderzocht met hoeveel procent de totale emissie van fijnstof door het wegvervoer in de periode 1990 tot en met 2014 is gedaald. Daarvoor moeten bovenstaande gegevens over het aantal gereden kilometers en onderstaande aannames over de fijnstofemissie per gereden kilometer worden gebruikt.$$, 'inline'),
  ('0149bda8-28cf-4ad0-ae24-b1f147b445ac', '92a2ca27-f059-466a-89c7-95a3c20a6f53', $$aannames: emissie per km in 1990 en afname per jaar$$,
   $$wiskunde-a-havo-2021-i-fijnstofemissie-context4.png$$,
   $$In 1990 kwam er gemiddeld genomen bij het personenvervoer per gereden kilometer 0,08 gram fijnstof vrij. Voor het goederenvervoer was dit toen 0,58 gram. In de periode 1990 tot en met 2014 daalde de fijnstofemissie bij het personenvervoer elk jaar met 0,003 gram per gereden kilometer. In dezelfde periode daalde de fijnstofemissie per gereden kilometer bij het goederenvervoer met 9% per jaar.$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('f3e439dc-fb9c-4317-a950-210fe78b2a35', '664ee2dd-cff4-4b4f-882d-08fd0a2b716d', 1,
   '[{"domain": "Algebra en tellen", "subdomain": "Rekenen"}, {"domain": "Algebra en tellen", "subdomain": "Algebra"}]'::jsonb,
   '["verhouding", "breuken", "evenredigheid", "aantal keer zo groot", "tabel aflezen"]'::jsonb,
