   $$wiskunde-a-havo-2021-i-visus-vraag1.png$$, $$3p 1 Bereken hoeveel keer zo dicht Klaas bij de Snellenkaart moet staan als Lidy om hetzelfde te kunnen lezen als Lidy.$$, array['d690e584-6831-4f20-9667-9d03af036f66', '0e88db67-4c83-4786-b4ff-f67fe0081362', '00104ef2-6b33-47f8-9b8a-9994b1691d58', '2c455dd2-79b8-44b3-b24b-cf1087fc5aaf']::uuid[]),
  ('40d6bf73-05c1-484e-8039-ea7234670f44', '664ee2dd-cff4-4b4f-882d-08fd0a2b716d', 2,
