  ('a6cc24ec-724e-4434-bcaa-18f6549c360d', '664ee2dd-cff4-4b4f-882d-08fd0a2b716d', 3,
   '[{"domain": "Verbanden", "subdomain": "Formules met één of meer variabelen"}]'::jsonb,
   '["substitueren", "exponentiële formule", "machten van 10", "ongelijkheid controleren", "formule invullen"]'::jsonb,
   $$Door substitutie in een exponentiële formule nagaan of een uitkomst aan een minimumeis voldoet.$$,
   $$wiskunde-a-havo-2021-i-visus-vraag3.png$$, $$3p 3 Wordt Janne goedgekeurd door het CBR? Licht je antwoord toe met een berekening.$$, array['00104ef2-6b33-47f8-9b8a-9994b1691d58', 'fcffc4d9-8254-4ee5-94d5-7849bcec3531', '381a4f3d-fc75-4abe-9f1e-02fb2c8d02b2']::uuid[]),
