   '["redeneren met formules", "afnemend verband", "stijgend en dalend", "exponent", "machten van 10"]'::jsonb,
   $$Zonder getallenvoorbeelden redeneren hoe twee variabelen via twee exponentiële formules van elkaar afhangen.$$,
   $$wiskunde-a-havo-2021-i-visus-vraag4.png$$, $$3p 4 Geef deze redenering, zonder gebruik te maken van getallenvoorbeelden.$$, array['00104ef2-6b33-47f8-9b8a-9994b1691d58', 'fcffc4d9-8254-4ee5-94d5-7849bcec3531', '22386b60-5b51-4991-ae9b-2a69bec58cd5']::uuid[]),
