   $$wiskunde-a-havo-2021-i-de-voorsteekpas-vraag10.png$$, $$3p 10 Bereken hoeveel minuten de gemiddelde wachttijd van een bezoeker voor de Vampire in de zomermaanden is.$$, array['5eca892f-5203-49dd-a2b5-a3440fd8f1e9', 'a0a22701-9e45-4855-88ae-957eadcbd01e']::uuid[]),
